"""Citations are retrieved from scholarly registries, never generated by an LLM."""

from __future__ import annotations

import asyncio
import html
import os
import re
from datetime import UTC, datetime
from difflib import SequenceMatcher

import httpx

EUROPE_PMC = "https://www.ebi.ac.uk/europepmc/webservices/rest/search"
CROSSREF = "https://api.crossref.org/works"


class CitationRetrievalError(Exception):
    pass


def plain(value):
    return html.unescape(re.sub(r"<[^>]+>", "", str(value or ""))).strip()


def crossref_record(item, endpoint):
    dates = item.get("published", item.get("issued", {})).get("date-parts", [[]])
    return {
        "title": plain((item.get("title") or [""])[0]),
        "authors": [
            " ".join(filter(None, [a.get("given"), a.get("family")]))
            for a in item.get("author", [])
        ],
        "year": dates[0][0] if dates and dates[0] else None,
        "venue": (item.get("container-title") or [""])[0],
        "doi": item.get("DOI", "").lower(),
        "url": "https://doi.org/" + item.get("DOI", ""),
        "abstract": plain(item.get("abstract")),
        "source": "Crossref",
        "source_url": endpoint,
        "verified_at": datetime.now(UTC).isoformat(),
    }


async def search_verified(query: str, limit=8) -> list[dict]:
    async with httpx.AsyncClient(
        timeout=httpx.Timeout(30, connect=10),
        headers={"User-Agent": "PathLab/1.0 scholarly-citation-retrieval"},
    ) as client:

        async def europe():
            response = await client.get(
                EUROPE_PMC,
                params={
                    "query": query,
                    "format": "json",
                    "resultType": "core",
                    "pageSize": 15,
                },
            )
            response.raise_for_status()
            records = []
            for item in response.json().get("resultList", {}).get("result", []):
                if not item.get("abstractText") or item.get("isRetracted") == "Y":
                    continue
                source, identifier = item.get("source"), item.get("id")
                if source not in {"MED", "PMC"} or not identifier:
                    continue
                info = item.get("journalInfo", {})
                url = f"https://europepmc.org/article/{source}/{identifier}"
                records.append(
                    {
                        "title": plain(item.get("title")),
                        "authors": [
                            a.get("fullName", "")
                            for a in item.get("authorList", {}).get("author", [])
                        ],
                        "year": item.get("pubYear"),
                        "venue": info.get("journal", {}).get("title", ""),
                        "abstract": plain(item.get("abstractText")),
                        "doi": (item.get("doi") or "").lower(),
                        "pmid": identifier if source == "MED" else item.get("pmid", ""),
                        "url": url,
                        "source": "Europe PMC / PubMed",
                        "source_url": str(response.url),
                        "verified_at": datetime.now(UTC).isoformat(),
                    }
                )
            return records

        async def crossref():
            response = await client.get(
                CROSSREF,
                params={
                    "query.bibliographic": query,
                    "rows": 12,
                    "filter": "has-abstract:true",
                },
            )
            response.raise_for_status()
            return [
                crossref_record(item, str(response.url))
                for item in response.json()["message"]["items"]
                if item.get("DOI")
                and item.get("abstract")
                and item.get("type") in {"journal-article", "proceedings-article"}
            ]

        async def scholar():
            key = os.getenv("PATHLAB_SERPAPI_KEY")
            if not key:
                return []
            response = await client.get(
                "https://serpapi.com/search.json",
                params={
                    "engine": "google_scholar",
                    "q": query,
                    "num": 5,
                    "api_key": key,
                },
            )
            response.raise_for_status()
            records = []
            for hit in response.json().get("organic_results", [])[:5]:
                await asyncio.sleep(1)  # Crossref list request courtesy limit.
                verification = await client.get(
                    CROSSREF, params={"query.title": hit["title"], "rows": 1}
                )
                verification.raise_for_status()
                items = verification.json()["message"]["items"]
                if not items:
                    continue
                record = crossref_record(items[0], str(verification.url))
                normalize = lambda value: re.sub(
                    r"\W+", " ", plain(value).lower()
                ).strip()
                if (
                    SequenceMatcher(
                        None, normalize(record["title"]), normalize(hit["title"])
                    ).ratio()
                    >= 0.92
                    and record["abstract"]
                ):
                    record["discovered_via"] = "Google Scholar / SerpApi"
                    records.append(record)
            return records

        results = await asyncio.gather(
            europe(), crossref(), scholar(), return_exceptions=True
        )
    unique = {}
    for result in results:
        if isinstance(result, Exception):
            continue
        for record in result:
            if (
                record["title"]
                and record["authors"]
                and record["year"]
                and record["abstract"]
            ):
                key = record.get("doi") or record.get("pmid") or record["title"].lower()
                unique.setdefault(key, record)
    if len(unique) < 2:
        raise CitationRetrievalError("citations_unavailable")
    return [
        {**record, "number": i + 1}
        for i, record in enumerate(list(unique.values())[:limit])
    ]


def citation_numbers(text: str) -> set[int]:
    numbers = set()
    for match in citation_matches(text):
        group = match.group(1)
        for part in group.split(","):
            ends = re.split(r"[–-]", part)
            if len(ends) == 2:
                start, end = map(int, ends)
                if end < start or end - start > 100:
                    raise ValueError("invalid_citations")
                numbers.update(range(start, end + 1))
            else:
                numbers.add(int(part))
    return numbers


def citation_matches(text: str):
    """Numeric bibliography markers, excluding nested arrays such as confusion matrices."""
    matrices = [
        match.span()
        for match in re.finditer(
            r"\[\s*\[[\d\s.,eE+\-]+\](?:\s*,\s*\[[\d\s.,eE+\-]+\])+\s*\]", text
        )
    ]
    for match in re.finditer(r"\[(\d+(?:\s*[,–-]\s*\d+)*)\]", text):
        if any(start <= match.start() < end for start, end in matrices):
            continue
        yield match


def finalize_numbers(text: str, references: list[dict]) -> tuple[str, list[dict]]:
    """Number cited registry records consecutively, in first-appearance order."""
    mapping = {}
    by_number = {ref["number"]: ref for ref in references}

    def replace(match):
        numbers = sorted(citation_numbers(match.group(0)))
        for number in numbers:
            if number not in by_number:
                raise ValueError("invalid_citations")
            mapping.setdefault(number, len(mapping) + 1)
        return "[" + ", ".join(str(mapping[number]) for number in numbers) + "]"

    result, start = [], 0
    for match in citation_matches(text):
        result.extend([text[start : match.start()], replace(match)])
        start = match.end()
    result.append(text[start:])
    return "".join(result), [
        {**by_number[old], "number": new} for old, new in mapping.items()
    ]


def bibtex(references: list[dict]) -> str:
    def escape(value):
        return (
            str(value or "")
            .replace("\\", "\\textbackslash{}")
            .replace("{", "\\{")
            .replace("}", "\\}")
        )

    return "\n\n".join(
        "@article{ref"
        + str(ref["number"])
        + ",\n"
        + ",\n".join(
            f"  {key} = {{{escape(value)}}}"
            for key, value in {
                "title": ref["title"],
                "author": " and ".join(ref["authors"]),
                "journal": ref["venue"],
                "year": ref["year"],
                "doi": ref.get("doi"),
                "url": ref["url"],
            }.items()
            if value
        )
        + "\n}"
        for ref in references
    )
